
package kr.ac.knue.cms.user;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.test.web.servlet.MockMvc;import java.util.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(UserManagementController.class) class UserManagementControllerTest{@Autowired MockMvc mvc;@MockBean UserManagementService service;@Test void list_users_returns_korus_readonly_fields_and_roles() throws Exception{when(service.list(anyMap())).thenReturn(List.of(Map.of("staffNo","10002","staffName","홍길동","positionName","학과장","lastSyncedAt","2026-07-31T09:00:00","roleCodes","R02")));mvc.perform(get("/api/users?staffNo=10002")).andExpect(status().isOk()).andExpect(jsonPath("$.data[0].staffNo").value("10002")).andExpect(jsonPath("$.data[0].positionName").value("학과장"));}@Test void update_usage_persists_local_useyn_only() throws Exception{when(service.updateUsage(eq("USER-10002"),eq("N"),any())).thenReturn(Map.of("userId","USER-10002","useYn","N"));mvc.perform(patch("/api/users/USER-10002/usage").contentType("application/json").content("{\"useYn\":\"N\",\"staffName\":\"변경금지\"}" )).andExpect(status().isOk()).andExpect(jsonPath("$.data.useYn").value("N"));}}
